#include "app.h"
#include <stdlib.h>
int main(int argc, char **argv) {
    FILE *input = argc > 1 ? fopen(argv[1], "r") : stdin;
    if (input == NULL) { perror("input"); return EXIT_FAILURE; }
    Row *rows = NULL;
    size_t count = 0;
    if (load_rows(input, &rows, &count) != 0) {
        if (input != stdin) fclose(input);
        return EXIT_FAILURE;
    }
    if (input != stdin) fclose(input);
    atexit(on_exit_report);
    qsort(rows, count, sizeof *rows, compare_rows);
    Summary summary = summarize(rows, count);
    int status = write_report(stdout, rows, count, &summary);
    free(rows);
    return status == 0 ? EXIT_SUCCESS : EXIT_FAILURE;
}

