#include "app.h"
#include <stdlib.h>
#include <string.h>
#define SLOT_NAME parse_calls
#include "slot.h"
#undef SLOT_NAME
#define SLOT_NAME parse_errors
#include "slot.h"
#undef SLOT_NAME
_Atomic size_t records_loaded;
int load_rows(FILE *input, Row **output, size_t *count) {
    char line[128];
    size_t used = 0, capacity = 4;
    Row *rows = malloc(capacity * sizeof *rows);
    if (rows == NULL) return -1;
    while (fgets(line, sizeof line, input) != NULL) {
        int id, consumed;
        double raw;
        char label[32];
        ++parse_calls;
        if (sscanf(line, "%d,%lf,%31[^\n]%n", &id, &raw, label, &consumed) != 3) {
            ++parse_errors; continue;
        }
        if (used == capacity) {
            capacity *= 2;
            Row *grown = realloc(rows, capacity * sizeof *rows);
            if (grown == NULL) { free(rows); return -1; }
            rows = grown;
        }
        rows[used].id = id;
        rows[used].value = (metric_t)raw;
        memcpy(rows[used].label, label, strlen(label) + 1);
        ++used;
        atomic_fetch_add_explicit(&records_loaded, 1, memory_order_relaxed);
    }
    *output = rows;
    *count = used;
    return 0;
}
int compare_rows(const void *a, const void *b) {
    const Row *left = a, *right = b;
    return (left->id > right->id) - (left->id < right->id);
}

