#include "app.h"
#include <math.h>
#include <assert.h>
#define MAGNITUDE(value) _Generic((value), float: fabsf, double: fabs)(value)
Summary summarize(const Row *rows, size_t count) {
    Summary summary = {0};
    assert(count == 0 || rows != NULL);
    double total = 0, squares = 0;
    for (size_t i = 0; i < count; ++i) {
        total += MAGNITUDE(rows[i].value);
        squares += pow((double)rows[i].value, 2);
    }
    if (count == 0) return summary;
    summary.average = total / count;
    summary.deviation = sqrt(fmax(squares / count - pow(summary.average, 2), 0.0));
    summary.rounded = round(summary.average);
#if APP_DIAGNOSTICS
    fprintf(stderr, "average=%g\n", summary.average);
#else
    (void)summary.rounded;
#endif
    return summary;
}

