#include "app.h"
#include <stdarg.h>
#include <time.h>
#include <inttypes.h>
static void message(FILE *stream, const char *format, ...) {
    va_list args;
    va_start(args, format);
    vfprintf(stream, format, args);
    va_end(args);
}
int write_report(FILE *output, const Row *rows, size_t count, const Summary *summary) {
    int written = 0;
    time_t now = time(NULL);
    fprintf(output, "%zu rows; mean=%.*f; deviation=%.3f%n\n",
            count, 3, summary->average, summary->deviation, &written);
    for (size_t i = 0; i < count; ++i) {
        fprintf(output, "%" PRId32 ",%s\n", (int32_t)rows[i].id, rows[i].label);
    }
    message(output, "offset=%zu; time=%ld\n", offsetof(Row, value), (long)now);
    size_t loaded = atomic_load_explicit(&records_loaded, memory_order_relaxed);
    return written >= 0 && loaded >= count ? 0 : -1;
}
void on_exit_report(void) { }
